import { useState } from "react";

// ── inline styles (no extra CSS file needed) ──────────────────────
const S = {
  page: {
    minHeight: "100vh",
    display: "flex",
    fontFamily: "'DM Sans', 'Segoe UI', sans-serif",
    background: "#fafaf8",
  },

  /* ── Left panel ── */
  left: {
    flex: 1,
    background: "#0a0a0a",
    display: "flex",
    flexDirection: "column",
    justifyContent: "space-between",
    padding: "48px",
    position: "relative",
    overflow: "hidden",
  },
  leftGlow: {
    position: "absolute",
    inset: 0,
    background:
      "radial-gradient(ellipse at 20% 80%, rgba(201,168,76,.20) 0%, transparent 55%), radial-gradient(ellipse at 80% 20%, rgba(201,168,76,.10) 0%, transparent 50%)",
    pointerEvents: "none",
  },
  leftContent: { position: "relative", zIndex: 1 },
  logo: {
    fontFamily: "'Playfair Display', Georgia, serif",
    fontSize: "28px",
    fontWeight: 900,
    color: "#fff",
    textDecoration: "none",
    display: "block",
    marginBottom: "64px",
  },
  logoSpan: { color: "#c9a84c" },
  tagline: {
    fontFamily: "'Playfair Display', Georgia, serif",
    fontSize: "clamp(28px, 3.5vw, 48px)",
    fontWeight: 700,
    color: "#fff",
    lineHeight: 1.1,
    marginBottom: "16px",
  },
  taglineAccent: { color: "#c9a84c" },
  taglineSub: {
    fontSize: "16px",
    color: "rgba(255,255,255,.5)",
    lineHeight: 1.65,
    maxWidth: "380px",
    marginBottom: "48px",
  },
  features: { display: "flex", flexDirection: "column", gap: "16px" },
  feature: { display: "flex", alignItems: "center", gap: "12px", fontSize: "15px", color: "rgba(255,255,255,.7)" },
  featureIcon: {
    width: "38px", height: "38px", borderRadius: "50%",
    background: "rgba(201,168,76,.15)", border: "1px solid rgba(201,168,76,.3)",
    display: "flex", alignItems: "center", justifyContent: "center",
    fontSize: "17px", flexShrink: 0,
  },
  leftFooter: { position: "relative", zIndex: 1, fontSize: "13px", color: "rgba(255,255,255,.25)" },

  /* ── Right panel ── */
  right: {
    width: "520px",
    background: "#fafaf8",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    padding: "48px 40px",
  },
  box: { width: "100%", maxWidth: "400px" },

  /* ── Tabs ── */
  tabs: {
    display: "flex",
    border: "1.5px solid #e0dbd2",
    borderRadius: "8px",
    overflow: "hidden",
    marginBottom: "36px",
  },
  tab: {
    flex: 1, padding: "12px", textAlign: "center",
    fontSize: "15px", fontWeight: 500, cursor: "pointer",
    border: "none", background: "transparent",
    color: "#9b9690", transition: "all .2s",
    fontFamily: "'DM Sans', sans-serif",
  },
  tabActive: {
    flex: 1, padding: "12px", textAlign: "center",
    fontSize: "15px", fontWeight: 600, cursor: "pointer",
    border: "none", background: "#0a0a0a", color: "#fff",
    fontFamily: "'DM Sans', sans-serif",
  },

  /* ── Form ── */
  title: {
    fontFamily: "'Playfair Display', Georgia, serif",
    fontSize: "28px", fontWeight: 700,
    color: "#0a0a0a", marginBottom: "6px",
  },
  subtitle: { fontSize: "14px", color: "#9b9690", marginBottom: "28px" },
  group: { marginBottom: "18px" },
  label: { display: "block", fontSize: "13px", fontWeight: 500, color: "#5a5650", marginBottom: "7px" },
  input: {
    width: "100%", height: "48px", padding: "0 16px",
    border: "1.5px solid #e0dbd2", borderRadius: "8px",
    fontFamily: "'DM Sans', sans-serif", fontSize: "15px",
    color: "#0a0a0a", background: "#fafaf8",
    outline: "none", boxSizing: "border-box",
    transition: "border-color .2s, box-shadow .2s",
  },
  inputFocus: {
    borderColor: "#c9a84c",
    boxShadow: "0 0 0 4px rgba(201,168,76,.12)",
  },
  inputWrap: { position: "relative" },
  eyeBtn: {
    position: "absolute", right: "14px", top: "50%",
    transform: "translateY(-50%)", background: "none",
    border: "none", cursor: "pointer", fontSize: "18px",
    color: "#9b9690", padding: 0,
  },
  forgotRow: { display: "flex", justifyContent: "flex-end", marginTop: "-10px", marginBottom: "18px" },
  forgotLink: { fontSize: "13px", color: "#c9a84c", textDecoration: "none", fontWeight: 500 },
  checkRow: { display: "flex", alignItems: "center", gap: "10px", marginBottom: "22px" },
  checkLabel: { fontSize: "13px", color: "#5a5650" },
  submitBtn: {
    width: "100%", height: "52px",
    background: "#0a0a0a", color: "#fff",
    border: "none", borderRadius: "8px",
    fontFamily: "'DM Sans', sans-serif",
    fontSize: "16px", fontWeight: 600,
    cursor: "pointer", transition: "all .25s",
    display: "flex", alignItems: "center", justifyContent: "center", gap: "8px",
  },
  divider: {
    display: "flex", alignItems: "center", gap: "12px",
    color: "#9b9690", fontSize: "13px", margin: "22px 0",
  },
  divLine: { flex: 1, height: "1px", background: "#e0dbd2" },
  social: { display: "grid", gridTemplateColumns: "1fr 1fr", gap: "12px" },
  socialBtn: {
    height: "48px", border: "1.5px solid #e0dbd2",
    borderRadius: "8px", background: "#fff",
    cursor: "pointer", fontFamily: "'DM Sans', sans-serif",
    fontSize: "14px", fontWeight: 500, color: "#0a0a0a",
    display: "flex", alignItems: "center", justifyContent: "center", gap: "8px",
    transition: "all .2s",
  },
  footer: { textAlign: "center", marginTop: "24px", fontSize: "14px", color: "#9b9690" },
  footerLink: { color: "#c9a84c", textDecoration: "none", fontWeight: 500 },

  /* ── OTP section ── */
  otpRow: { display: "flex", gap: "10px", justifyContent: "center", margin: "24px 0" },
  otpInput: {
    width: "52px", height: "56px", textAlign: "center",
    fontFamily: "'DM Mono', monospace", fontSize: "22px", fontWeight: 600,
    border: "2px solid #e0dbd2", borderRadius: "8px",
    outline: "none", background: "#fafaf8",
    transition: "border-color .2s, box-shadow .2s",
  },
  backBtn: {
    background: "none", border: "none", color: "#c9a84c",
    fontSize: "13px", fontWeight: 500, cursor: "pointer",
    display: "flex", alignItems: "center", gap: "4px",
    padding: 0, marginBottom: "20px",
    fontFamily: "'DM Sans', sans-serif",
  },
  resend: { textAlign: "center", fontSize: "13px", color: "#9b9690", marginTop: "14px" },
  resendLink: { color: "#c9a84c", cursor: "pointer", fontWeight: 500 },

  /* ── Alert / Error ── */
  alert: {
    padding: "12px 14px", borderRadius: "8px",
    fontSize: "13px", marginBottom: "16px",
    display: "flex", alignItems: "center", gap: "8px",
  },
  alertError: { background: "#fee2e2", color: "#991b1b", border: "1px solid #fca5a5" },
  alertSuccess: { background: "#dcfce7", color: "#166534", border: "1px solid #86efac" },
};

// ── Helper: focus style ──────────────────────────────────────────
function useFocus() {
  const [focused, setFocused] = useState(false);
  return {
    style: focused ? { ...S.input, ...S.inputFocus } : S.input,
    onFocus: () => setFocused(true),
    onBlur: () => setFocused(false),
  };
}

// ── OTP Input Component ──────────────────────────────────────────
function OTPInput({ length = 6, value, onChange }) {
  const digits = value.split("").concat(Array(length).fill("")).slice(0, length);

  const handleChange = (e, idx) => {
    const val = e.target.value.replace(/\D/g, "").slice(0, 1);
    const next = [...digits];
    next[idx] = val;
    onChange(next.join(""));
    if (val && idx < length - 1) {
      document.getElementById(`otp-login-${idx + 1}`)?.focus();
    }
  };

  const handleKeyDown = (e, idx) => {
    if (e.key === "Backspace" && !digits[idx] && idx > 0) {
      document.getElementById(`otp-login-${idx - 1}`)?.focus();
    }
  };

  const handlePaste = (e) => {
    e.preventDefault();
    const text = e.clipboardData.getData("text").replace(/\D/g, "").slice(0, length);
    onChange(text.padEnd(length, ""));
    document.getElementById(`otp-login-${Math.min(text.length, length - 1)}`)?.focus();
  };

  return (
    <div style={S.otpRow}>
      {digits.map((d, i) => (
        <input
          key={i}
          id={`otp-login-${i}`}
          type="text"
          inputMode="numeric"
          maxLength={1}
          value={d}
          style={{
            ...S.otpInput,
            ...(d ? { borderColor: "#c9a84c", boxShadow: "0 0 0 3px rgba(201,168,76,.15)" } : {}),
          }}
          onChange={(e) => handleChange(e, i)}
          onKeyDown={(e) => handleKeyDown(e, i)}
          onPaste={handlePaste}
        />
      ))}
    </div>
  );
}

// ── Main Login Component ─────────────────────────────────────────
export default function Login() {
  const [tab, setTab] = useState("login"); // 'login' | 'register'

  // Login state
  const [identifier, setIdentifier] = useState("");
  const [password, setPassword] = useState("");
  const [showPass, setShowPass] = useState(false);
  const [rememberMe, setRememberMe] = useState(true);
  const [loginLoading, setLoginLoading] = useState(false);
  const [loginError, setLoginError] = useState("");
  const [showOTP, setShowOTP] = useState(false);
  const [otpValue, setOtpValue] = useState("");
  const [otpTimer, setOtpTimer] = useState(0);

  // Register state — redirect to Register page
  const navigateToRegister = () => {
    window.location.href = "/register";
  };

  // ── Countdown timer ──
  const startTimer = () => {
    setOtpTimer(30);
    const interval = setInterval(() => {
      setOtpTimer((t) => {
        if (t <= 1) { clearInterval(interval); return 0; }
        return t - 1;
      });
    }, 1000);
  };

  // ── Handle login submit ──
  const handleLogin = () => {
    setLoginError("");
    if (!identifier.trim()) { setLoginError("Please enter your email or phone number."); return; }
    if (!password) { setLoginError("Please enter your password."); return; }

    setLoginLoading(true);
    setTimeout(() => {
      setLoginLoading(false);
      // Simulate: if phone number → show OTP
      if (/^\d{10}$/.test(identifier.replace(/\s/g, ""))) {
        setShowOTP(true);
        startTimer();
      } else {
        // Email login → redirect home
        window.location.href = "/";
      }
    }, 1200);
  };

  // ── Verify OTP ──
  const verifyOTP = () => {
    if (otpValue.replace(/\D/g, "").length < 6) {
      setLoginError("Please enter all 6 digits.");
      return;
    }
    setLoginLoading(true);
    setTimeout(() => {
      setLoginLoading(false);
      window.location.href = "/";
    }, 1000);
  };

  // ── Social auth ──
  const socialAuth = (provider) => {
    console.log("Connecting to", provider);
    // TODO: integrate OAuth
    setTimeout(() => { window.location.href = "/"; }, 1500);
  };

  // ── Forgot password ──
  const handleForgot = (e) => {
    e.preventDefault();
    alert("Password reset link sent to your email!");
  };

  // ── Input helpers ──
  const [idFocus, setIdFocus] = useState(false);
  const [pwFocus, setPwFocus] = useState(false);

  return (
    <div style={S.page}>
      {/* ── Left panel ── */}
      <div style={S.left}>
        <div style={S.leftGlow} />
        <div style={S.leftContent}>
          <a href="/" style={S.logo}>
            The<span style={S.logoSpan}>Zuro</span>
          </a>
          <div>
            <h2 style={S.tagline}>
              Welcome to <span style={S.taglineAccent}>TheZuro</span>
            </h2>
            <p style={S.taglineSub}>
              Join millions of shoppers discovering the best deals from India's top sellers.
            </p>
            <div style={S.features}>
              {[
                ["🛍", "50,000+ products across every category"],
                ["🚀", "Free delivery on orders above ₹499"],
                ["🔒", "100% secure payments & easy returns"],
                ["⭐", "Exclusive member-only deals & cashback"],
              ].map(([icon, text]) => (
                <div key={text} style={S.feature}>
                  <div style={S.featureIcon}>{icon}</div>
                  <span>{text}</span>
                </div>
              ))}
            </div>
          </div>
        </div>
        <div style={S.leftFooter}>© 2025 TheZuro. All rights reserved.</div>
      </div>

      {/* ── Right panel ── */}
      <div style={S.right}>
        <div style={S.box}>
          {/* Tabs */}
          <div style={S.tabs}>
            <button
              style={tab === "login" ? S.tabActive : S.tab}
              onClick={() => setTab("login")}
            >
              Sign In
            </button>
            <button
              style={tab === "register" ? S.tabActive : S.tab}
              onClick={navigateToRegister}
            >
              Create Account
            </button>
          </div>

          {/* ── LOGIN FORM ── */}
          {!showOTP ? (
            <>
              <h1 style={S.title}>Welcome back 👋</h1>
              <p style={S.subtitle}>Sign in to your TheZuro account</p>

              {loginError && (
                <div style={{ ...S.alert, ...S.alertError }}>
                  ⚠️ {loginError}
                </div>
              )}

              {/* Identifier */}
              <div style={S.group}>
                <label style={S.label}>Email or Phone Number</label>
                <input
                  style={{ ...S.input, ...(idFocus ? S.inputFocus : {}) }}
                  type="text"
                  placeholder="Enter email or 10-digit phone"
                  value={identifier}
                  onChange={(e) => setIdentifier(e.target.value)}
                  onFocus={() => setIdFocus(true)}
                  onBlur={() => setIdFocus(false)}
                  onKeyDown={(e) => e.key === "Enter" && handleLogin()}
                />
              </div>

              {/* Password */}
              <div style={S.group}>
                <label style={S.label}>Password</label>
                <div style={S.inputWrap}>
                  <input
                    style={{ ...S.input, paddingRight: "48px", ...(pwFocus ? S.inputFocus : {}) }}
                    type={showPass ? "text" : "password"}
                    placeholder="Enter your password"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    onFocus={() => setPwFocus(true)}
                    onBlur={() => setPwFocus(false)}
                    onKeyDown={(e) => e.key === "Enter" && handleLogin()}
                  />
                  <button style={S.eyeBtn} onClick={() => setShowPass(!showPass)} type="button">
                    {showPass ? "🙈" : "👁"}
                  </button>
                </div>
              </div>

              {/* Forgot + Remember */}
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "20px" }}>
                <label style={{ ...S.checkRow, margin: 0 }}>
                  <input
                    type="checkbox"
                    checked={rememberMe}
                    onChange={(e) => setRememberMe(e.target.checked)}
                    style={{ accentColor: "#c9a84c", width: "16px", height: "16px" }}
                  />
                  <span style={S.checkLabel}>Remember me</span>
                </label>
                <a href="#" style={S.forgotLink} onClick={handleForgot}>
                  Forgot password?
                </a>
              </div>

              {/* Submit */}
              <button
                style={{
                  ...S.submitBtn,
                  opacity: loginLoading ? 0.7 : 1,
                  cursor: loginLoading ? "not-allowed" : "pointer",
                }}
                onClick={handleLogin}
                disabled={loginLoading}
              >
                {loginLoading ? "⏳ Signing in…" : "Sign In →"}
              </button>

              {/* Divider */}
              <div style={S.divider}>
                <div style={S.divLine} /> or continue with <div style={S.divLine} />
              </div>

              {/* Social */}
              <div style={S.social}>
                <button
                  style={S.socialBtn}
                  onClick={() => socialAuth("Google")}
                  onMouseOver={(e) => (e.target.style.background = "#f5f5f5")}
                  onMouseOut={(e) => (e.target.style.background = "#fff")}
                >
                  <span style={{ fontSize: "18px" }}>G</span> Google
                </button>
                <button
                  style={S.socialBtn}
                  onClick={() => socialAuth("Facebook")}
                  onMouseOver={(e) => (e.target.style.background = "#f5f5f5")}
                  onMouseOut={(e) => (e.target.style.background = "#fff")}
                >
                  <span style={{ fontSize: "18px" }}>📘</span> Facebook
                </button>
              </div>

              <p style={S.footer}>
                New to TheZuro?{" "}
                <a href="/register" style={S.footerLink}>
                  Create account
                </a>
              </p>
            </>
          ) : (
            /* ── OTP Screen ── */
            <>
              <button style={S.backBtn} onClick={() => { setShowOTP(false); setOtpValue(""); setLoginError(""); }}>
                ← Back
              </button>
              <h1 style={S.title}>Enter OTP 🔐</h1>
              <p style={S.subtitle}>
                We sent a 6-digit code to{" "}
                <strong>+91 {identifier}</strong>
              </p>

              {loginError && (
                <div style={{ ...S.alert, ...S.alertError }}>⚠️ {loginError}</div>
              )}

              <OTPInput length={6} value={otpValue} onChange={setOtpValue} />

              <button
                style={{
                  ...S.submitBtn,
                  opacity: loginLoading ? 0.7 : 1,
                  cursor: loginLoading ? "not-allowed" : "pointer",
                }}
                onClick={verifyOTP}
                disabled={loginLoading}
              >
                {loginLoading ? "⏳ Verifying…" : "Verify & Sign In →"}
              </button>

              <p style={S.resend}>
                Didn't receive?{" "}
                {otpTimer > 0 ? (
                  <span style={{ color: "#9b9690" }}>Resend in {otpTimer}s</span>
                ) : (
                  <span
                    style={S.resendLink}
                    onClick={() => { setOtpValue(""); startTimer(); }}
                  >
                    Resend OTP
                  </span>
                )}
              </p>
            </>
          )}
        </div>
      </div>

      {/* ── Responsive: hide left panel on small screens ── */}
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;900&family=DM+Sans:wght@400;500;600&family=DM+Mono:wght@500&display=swap');
        @media (max-width: 900px) {
          .login-left { display: none !important; }
          .login-right { width: 100% !important; }
        }
        button:hover { opacity: 0.88; }
      `}</style>
    </div>
  );
}
